from __future__ import annotations

from ui.format import LINE_LENGTH, format_python
from ui.inline_edit import SQL_FORMAT, rules


def test_formats_as_ruff() -> None:
    assert format_python("x=1;y = [1,2 ]") == "x = 1\ny = [1, 2]"


def test_wraps_at_line_length() -> None:
    code = "out = q1.group_by('char').agg(pl.col('win').sum().alias('wins'),pl.len().alias('sets')).sort('wins')"
    pretty = format_python(code)
    assert pretty != code
    assert max(len(line) for line in pretty.splitlines()) <= LINE_LENGTH
    assert '"char"' in pretty  # ruff's double quotes


def test_keeps_the_trailing_newline_as_it_was() -> None:
    assert format_python("x=1\n") == "x = 1\n"
    assert format_python("x=1") == "x = 1"


def test_an_indented_block_keeps_its_indent() -> None:
    assert format_python("    x=1\n    y=2") == "    x = 1\n    y = 2"


def test_what_ruff_cannot_format_is_unchanged() -> None:
    for code in ("q1.filter(", "%timeit f()", "", "  \n"):
        assert format_python(code) == code


def test_sql_layout_is_told_for_sql_only() -> None:
    assert SQL_FORMAT in rules("sql")
    assert SQL_FORMAT not in rules("python")
    assert "SELECT\n  character,\n  move," in SQL_FORMAT  # the example keeps its indent
